// Checks a UniFi Alarm Manager webhook and answers it.
// Output 1: accepted request -> lock state check
// Output 2: HTTP response for Alarm Manager
//
// Locks this flow is allowed to unlock. The webhook URL chooses one with ?lock=<entity_id>
const ALLOWED_LOCKS = ["lock.front_door", "lock.garage"];
const MAX_AGE_SECONDS = 300; // reject alarms whose timestamp is older than 5 minutes

const token = env.get("ALARM_MANAGER_BEARER");
const allowedIps = String(env.get("ALARM_MANAGER_ALLOWED_IPS") || "")
    .split(",").map(s => s.trim()).filter(Boolean);

function respond(code, text) {
    return { req: msg.req, res: msg.res, statusCode: code, payload: text };
}
function reject(code, reason) {
    node.warn("Alarm Manager webhook rejected: " + reason);
    node.status({ fill: "red", shape: "ring", text: reason });
    return [null, respond(code, reason)];
}
function sameSecret(a, b) {
    // Hash both so the comparison is constant-time and length-independent
    const ha = crypto.createHash("sha256").update(String(a)).digest();
    const hb = crypto.createHash("sha256").update(String(b)).digest();
    return crypto.timingSafeEqual(ha, hb);
}

if (!token) {
    node.error("Flow environment variable ALARM_MANAGER_BEARER is not set");
    return reject(500, "not configured");
}

// 1. Optional source IP allow-list
if (allowedIps.length) {
    const ip = String(msg.req.ip || "").replace(/^::ffff:/, "");
    if (!allowedIps.includes(ip)) return reject(403, "source not allowed: " + ip);
}

// 2. Bearer token
const auth = String(msg.req.headers["authorization"] || "");
const match = auth.match(/^Bearer\s+(.+)$/i);
if (!match || !sameSecret(match[1].trim(), token)) return reject(401, "invalid token");

// 3. Lock chosen by the URL
const entity = String((msg.req.query && msg.req.query.lock) || "");
if (!ALLOWED_LOCKS.includes(entity)) return reject(400, "unknown lock: " + (entity || "(none)"));

// 4. Payload sanity
const body = msg.payload;
if (!body || typeof body !== "object" || !body.alarm || typeof body.alarm !== "object") {
    return reject(400, "not an Alarm Manager payload");
}

// 5. Freshness (Alarm Manager sends a millisecond timestamp)
const ts = Number(body.timestamp);
if (ts > 0 && Math.abs(Date.now() - ts) > MAX_AGE_SECONDS * 1000) {
    return reject(400, "alarm too old");
}

// 6. Ignore repeat deliveries of the same alarm
const key = [entity, body.alarm.name, body.timestamp,
    JSON.stringify((body.alarm.triggers || []).map(t => t && (t.eventId || t.key)))].join("|");
const seen = flow.get("alarmManagerSeen") || [];
if (seen.includes(key)) {
    node.status({ fill: "yellow", shape: "ring", text: "duplicate ignored" });
    return [null, respond(200, "duplicate")];
}
seen.push(key);
flow.set("alarmManagerSeen", seen.slice(-100));

node.status({ fill: "green", shape: "dot", text: `${body.alarm.name || "alarm"} → ${entity}` });
return [
    {
        payload: { entity_id: entity, action: "lock.unlock", target: { entity_id: [entity] } },
        alarm: { name: body.alarm.name, lock: entity, triggers: body.alarm.triggers },
    },
    respond(200, "ok"),
];
